cd /tmp/claude-0/-home-user-ClaudiniteWebsite/2d9cae83-ac25-5a12-bd9f-746fe84c50f9/scratchpad/logs
python3 -c "
import json
def render(fn, out):
    with open(fn) as f, open(out,'w') as o:
        for line in f:
            line=line.strip()
            if not line: continue
            try:
                d = json.loads(line)
            except Exception:
                continue
            t = d.get('type')
            ts = d.get('timestamp','')
            if t in ('user','assistant'):
                msg = d.get('message',{})
                role = msg.get('role')
                content = msg.get('content')
                text_parts=[]
                if isinstance(content, str):
                    text_parts.append(content)
                elif isinstance(content, list):
                    for c in content:
                        if not isinstance(c, dict): continue
                        ctype = c.get('type')
                        if ctype == 'text':
                            text_parts.append(c.get('text',''))
                        elif ctype == 'tool_use':
                            text_parts.append(f'[TOOL_USE {c.get(\"name\")}] input={json.dumps(c.get(\"input\"))[:300]}')
                        elif ctype == 'tool_result':
                            cc = c.get('content')
                            if isinstance(cc, list):
                                s = ' '.join(x.get('text','') for x in cc if isinstance(x,dict))
                            else:
                                s = str(cc)
                            text_parts.append(f'[TOOL_RESULT] {s[:300]}')
                o.write(f'--- {ts} {role} ---\n')
                o.write('\n'.join(text_parts))
                o.write('\n\n')
render('issue-217.jsonl','issue-217.txt')
render('issue-211.jsonl','issue-211.txt')
"
